import sqlite3
con = sqlite3.connect(":memory:")
cur = con.cursor()
cur.executescript("""
CREATE TABLE members (id INTEGER, email TEXT UNIQUE, region TEXT);
INSERT INTO members VALUES (1, 'ana@example.com', 'North');
INSERT INTO members VALUES (2, NULL, 'South');
INSERT INTO members VALUES (3, NULL, NULL);
INSERT INTO members VALUES (4, 'ben@example.com', NULL);
INSERT INTO members VALUES (5, NULL, 'North');
""")
print("members inserted OK:", cur.execute("SELECT COUNT(*) FROM members").fetchone()[0])
try:
    cur.execute("INSERT INTO members VALUES (6, 'ana@example.com', 'East')")
    print("duplicate real email: INSERTED (unexpected)")
except sqlite3.IntegrityError as e:
    print("duplicate real email rejected:", e)
for r in cur.execute("SELECT region, COUNT(*) FROM members GROUP BY region ORDER BY region"):
    print("region:", r[0], "count:", r[1])

import sqlite3
con = sqlite3.connect(":memory:")
cur = con.cursor()
cur.executescript("""
CREATE TABLE accounts (id INTEGER, email TEXT, active INTEGER);
CREATE UNIQUE INDEX ux_active_email ON accounts(email) WHERE active = 1;
INSERT INTO accounts VALUES (1, 'ana@example.com', 1);
INSERT INTO accounts VALUES (2, 'ben@example.com', 0);
INSERT INTO accounts VALUES (3, 'ben@example.com', 0);
""")
print("two INACTIVE accounts sharing an email: allowed")
def attempt(label, sql):
    try:
        cur.execute(sql); print(label, "-> INSERTED")
    except sqlite3.IntegrityError as e:
        print(label, "-> rejected:", e)
attempt("second ACTIVE ana@example.com", "INSERT INTO accounts VALUES (4, 'ana@example.com', 1)")
attempt("reactivating ben (id 2) while id 5 test", "INSERT INTO accounts VALUES (5, 'ben@example.com', 1)")
print("table:", cur.execute("SELECT id, email, active FROM accounts ORDER BY id").fetchall())
